<template><main class="flow-page"><section class="flow-card"><span class="step">第 1 步，共 1 步</span><h1>完善你的学习档案</h1><p class="hint">这些信息用于匹配教材、知识点与学习建议，之后可在个人中心修改。</p><form @submit.prevent="submit"><div class="form-item"><label class="form-label" for="nickname">姓名或昵称</label><input id="nickname" v-model.trim="form.nickname" class="input" maxlength="64" required /></div><div class="grid"><div class="form-item"><label class="form-label" for="stage">学段</label><select id="stage" v-model="form.stage" class="select"><option>小学</option><option>初中</option><option>高中</option><option>大学</option></select></div><div class="form-item"><label class="form-label" for="grade">年级</label><input id="grade" v-model.trim="form.grade" class="input" required placeholder="例如：高二" /></div></div><div class="form-item"><label class="form-label" for="school">学校（选填）</label><input id="school" v-model.trim="form.school" class="input" /></div><button class="btn btn-primary submit" :disabled="loading||!valid">{{loading?'保存中…':'进入学习空间'}}</button></form></section></main></template>
<script setup>
import { computed, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { authApi } from '@/api/auth'; import { useAuthStore } from '@/stores/auth'
const form=reactive({nickname:'',stage:'高中',grade:'',school:'',consent_version:'2026-08-22'}),loading=ref(false),router=useRouter(),auth=useAuthStore();const valid=computed(()=>form.nickname&&form.stage&&form.grade)
async function submit(){if(!valid.value||loading.value)return;loading.value=true;try{await authApi.onboardStudent(form);await auth.refreshMe();router.push('/overview')}finally{loading.value=false}}
</script>
<style scoped>.flow-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--bg)}.flow-card{width:min(600px,100%);padding:38px;background:white;border:1px solid var(--line);border-radius:22px;box-shadow:var(--shadow-md)}.step{color:var(--brand-deep);font-weight:700;font-size:12px}.hint{color:var(--ink2);margin:8px 0 24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.submit{width:100%;height:44px}@media(max-width:560px){.grid{grid-template-columns:1fr}}</style>
